diff --git a/src/price.ts b/src/price.ts
--- a/src/price.ts
+++ b/src/price.ts
@@ -1,5 +1,8 @@
 export type Item = { price: number; qty: number };

+const DISCOUNT_THRESHOLD = 100;
+const DISCOUNT_RATE = 0.1;
+
 export function subtotal(items: Item[]): number {
   return items.reduce((sum, item) => sum + item.price * item.qty, 0);
 }
@@ -9,5 +12,7 @@ function roundToCents(amount: number): number {
 }

 export function total(items: Item[]): number {
-  return roundToCents(subtotal(items));
+  const sub = subtotal(items);
+  const discounted = sub > DISCOUNT_THRESHOLD ? sub * (1 - DISCOUNT_RATE) : sub;
+  return roundToCents(discounted);
 }
